parameters.jsCode:
const raw = String($input.first().json.stdout || '').trim();

if (!raw || raw === '__CONFIG_NOT_FOUND__') {
  throw new Error('Configuration not found. Set SYNOPLEX_STACK_JSON or mount stack.json at /data/PlexMediaServer/stack.json');
}

let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('Invalid configuration loader response: ' + e.message);
}

if (cfg.configError) {
  throw new Error('Invalid stack.json: ' + cfg.configError);
}

const missing = [];

if (!cfg.plexApiTokenPresent) missing.push('plex.api_token');
if (!cfg.radarrUrl) missing.push('radarr.url');
if (!cfg.radarrApiKeyPresent) missing.push('radarr.api_key');
if (!cfg.sonarrUrl) missing.push('sonarr.url');
if (!cfg.sonarrApiKeyPresent) missing.push('sonarr.api_key');

if (missing.length) {
  throw new Error('Missing fields in stack.json: ' + missing.join(', '));
}

for (const [name, value] of [
  ['radarr.url', cfg.radarrUrl],
  ['sonarr.url', cfg.sonarrUrl]
]) {
  if (!/^https?:\/\//i.test(String(value || ''))) {
    throw new Error(name + ' must be a valid HTTP(S) URL');
  }
}

return [{
  json: {
    status: 'CONFIG_OK',
    plexUrl: cfg.plexUrl,
    radarrUrl: cfg.radarrUrl,
    sonarrUrl: cfg.sonarrUrl
  }
}];

parameters.command:
node <<'NODE'
const fs=require('fs');
const cfg=JSON.parse(fs.readFileSync((process.env.SYNOPLEX_STACK_JSON||'/data/PlexMediaServer/stack.json'),'utf8'));
const token=String(cfg.plex?.api_token||'').trim();
const CONFIG_ROOT=String(cfg.paths?.config_root||'').replace(/\/$/,'');
const N8N_CONFIG_ROOT=String(cfg.paths?.n8n_config_root||'/data/PlexMediaServer').replace(/\/$/,'');
const WATCHLIST_NAS=String(cfg.paths?.watchlist_state||'').trim();
const STATE=(WATCHLIST_NAS&&CONFIG_ROOT&&WATCHLIST_NAS.startsWith(CONFIG_ROOT))
  ? N8N_CONFIG_ROOT+WATCHLIST_NAS.slice(CONFIG_ROOT.length)
  : N8N_CONFIG_ROOT+'/watchlist-state.json';
const SELF_PAGE=100;
const FRIEND_PAGE=100;
const MAX_PROCESS_PER_RUN=8;
const MAX_SERIES_PER_RUN=8;
const LOCK='/home/node/.n8n/.plex-watchlist-reconcile.lock';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

let lockFd=null;
try{
  try{
    const st=fs.statSync(LOCK);
    if(Date.now()-st.mtimeMs>15*60*1000) fs.unlinkSync(LOCK);
  }catch{}
  lockFd=fs.openSync(LOCK,'wx');
}catch(e){
  if(e?.code==='EEXIST'){
    console.log(JSON.stringify({
      service:'plex-discover',
      mode:'skip-locked',
      complete:false,
      count:0,
      processCount:0,
      items:[],
      removed:[]
    }));
    process.exit(0);
  }
  throw e;
}
process.on('exit',()=>{
  try{if(lockFd!==null) fs.closeSync(lockFd)}catch{}
  try{fs.unlinkSync(LOCK)}catch{}
});

if(!token){
  console.error('plex.api_token missing');
  process.exit(1);
}

const plexHeaders={
  'X-Plex-Token':token,
  'X-Plex-Product':'PLEX Bootstrap Synology',
  'X-Plex-Version':'5.0',
  'X-Plex-Client-Identifier':'plex-bootstrap-synology-v8',
  'X-Plex-Platform':'n8n',
  'Accept':'application/json'
};

async function fetchJson(url,options={},attempts=3){
  let last;
  for(let i=1;i<=attempts;i++){
    try{
      const r=await fetch(url,{...options,signal:AbortSignal.timeout(15000)});
      const txt=await r.text();
      let data;
      try{data=txt?JSON.parse(txt):{}}catch{throw new Error('Invalid JSON from '+url+' :: '+txt.slice(0,300))}
      if(!r.ok) throw new Error('HTTP '+r.status+' '+url+' :: '+txt.slice(0,300));
      return data;
    }catch(e){
      last=e;
      if(i<attempts) await sleep(500*i);
    }
  }
  throw last||new Error('Unknown HTTP error');
}

async function gql(query,variables,operationName){
  return fetchJson('https://community.plex.tv/api',{
    method:'POST',
    headers:{
      ...plexHeaders,
      'Content-Type':'application/json'
    },
    body:JSON.stringify({query,variables,operationName})
  });
}

function compact(x){
  return {
    ratingKey:String(x.ratingKey||''),
    guid:String(x.guid||''),
    type:String(x.type||'').toLowerCase(),
    title:String(x.title||'').trim(),
    year:x.year==null?null:Number(x.year),
    watchlistedAt:x.watchlistedAt??null,
    guids:Array.isArray(x.guids)?x.guids.map(String):[],
    requestedBy:Array.isArray(x.requestedBy)?[...new Set(x.requestedBy.map(String))]:[]
  };
}

function keyOf(x){
  return String(x.ratingKey||x.guid||(x.type+':'+x.title+':'+(x.year??''))).trim();
}

function readState(){
  try{
    if(!fs.existsSync(STATE)) return {version:2,initialized:false,current:[],pendingRemoved:[],processCursor:0};
    const x=JSON.parse(fs.readFileSync(STATE,'utf8'));
    return {
      version:2,
      initialized:Boolean(x.initialized),
      current:Array.isArray(x.current)?x.current:[],
      pendingRemoved:Array.isArray(x.pendingRemoved)?x.pendingRemoved:[],
      processCursor:Number.isFinite(Number(x.processCursor))?Number(x.processCursor):0
    };
  }catch{
    return {version:2,initialized:false,current:[],pendingRemoved:[],processCursor:0};
  }
}

function writeState(state){
  const fd=fs.openSync(STATE,'w');
  try{
    fs.writeFileSync(fd,JSON.stringify(state,null,2));
    fs.fsyncSync(fd);
  }finally{fs.closeSync(fd);}
}

async function getSelfWatchlist(){
  const items=[];
  let start=0,total=null,complete=true,pages=0;

  for(let page=0;page<50;page++){
    const url=new URL('https://discover.provider.plex.tv/library/sections/watchlist/all');
    url.searchParams.set('includeCollections','1');
    url.searchParams.set('includeExternalMedia','1');
    url.searchParams.set('sort','watchlistedAt:desc');

    const data=await fetchJson(url,{
      headers:{
        ...plexHeaders,
        'X-Plex-Container-Start':String(start),
        'X-Plex-Container-Size':String(SELF_PAGE)
      }
    });

    const mc=data.MediaContainer||{};
    if(total==null){
      const n=Number(mc.totalSize??mc.total??mc.size);
      total=Number.isFinite(n)?n:null;
    }

    const rows=[]
      .concat(Array.isArray(mc.Metadata)?mc.Metadata:[])
      .concat(Array.isArray(mc.Video)?mc.Video:[])
      .concat(Array.isArray(mc.Directory)?mc.Directory:[]);

    pages++;
    if(!rows.length) break;

    for(const x of rows){
      const type=String(x.type||'').toLowerCase();
      if(!['movie','show'].includes(type)) continue;
      const title=String(x.title||'').trim();
      if(!title) continue;

      const guids=Array.isArray(x.Guid)?x.Guid.map(g=>String(g.id||'')).filter(Boolean):[];

      items.push(compact({
        ratingKey:x.ratingKey,
        guid:x.guid,
        type,
        title,
        year:x.year,
        watchlistedAt:x.watchlistedAt,
        guids,
        requestedBy:['self']
      }));
    }

    start+=rows.length;
    if(rows.length<SELF_PAGE) break;
    if(total!=null&&start>=total) break;
    if(page===49) complete=false;
  }

  if(total!=null&&start<total) complete=false;
  return {items,complete,total:total??items.length,pages};
}

const qFriends=[
  'query GetAllFriends {',
  '  allFriendsV2 {',
  '    user {',
  '      id',
  '      username',
  '    }',
  '  }',
  '}'
].join('\n');

const qWatch=[
  'query GetWatchlistHub ($uuid: ID = "", $first: PaginationInt!, $after: String) {',
  '  user(id: $uuid) {',
  '    watchlist(first: $first, after: $after) {',
  '      nodes {',
  '        ...itemFields',
  '      }',
  '      pageInfo {',
  '        hasNextPage',
  '        endCursor',
  '      }',
  '    }',
  '  }',
  '}',
  'fragment itemFields on MetadataItem {',
  '  id',
  '  title',
  '  type',
  '}'
].join('\n');

async function enrichFriendItem(friend,item){
  const id=String(item?.id||'').trim();
  if(!id) throw new Error('Friend item has no Plex ID');

  const data=await fetchJson('https://discover.provider.plex.tv/library/metadata/'+encodeURIComponent(id),{
    headers:plexHeaders
  });

  const m=data?.MediaContainer?.Metadata?.[0];
  if(!m) throw new Error('Plex metadata not found for '+id);

  const type=String(m.type||item.type||'').toLowerCase();
  const guids=Array.isArray(m.Guid)?m.Guid.map(g=>String(g.id||'')).filter(Boolean):[];

  return compact({
    ratingKey:m.ratingKey||id,
    guid:m.guid||'',
    type,
    title:m.title||item.title||'',
    year:m.year,
    guids,
    requestedBy:['@'+String(friend.username||friend.id)]
  });
}

async function getFriendsWatchlists(){
  const result={items:[],complete:true,friends:[],errors:[]};

  let friends;
  try{
    const fd=await gql(qFriends,{},'GetAllFriends');
    if(fd?.errors?.length) throw new Error(JSON.stringify(fd.errors).slice(0,500));
    friends=(fd?.data?.allFriendsV2||[]).map(x=>x?.user).filter(Boolean);
  }catch(e){
    result.complete=false;
    result.errors.push('friends: '+e.message);
    return result;
  }

  for(const friend of friends){
    let after=null,pages=0,count=0;
    const rawItems=[];

    try{
      do{
        const vars={uuid:String(friend.id),first:FRIEND_PAGE};
        if(after) vars.after=after;

        const wd=await gql(qWatch,vars,'GetWatchlistHub');
        if(wd?.errors?.length) throw new Error(JSON.stringify(wd.errors).slice(0,500));

        const wl=wd?.data?.user?.watchlist;
        const nodes=Array.isArray(wl?.nodes)?wl.nodes:[];

        rawItems.push(...nodes);
        count+=nodes.length;
        pages++;

        if(wl?.pageInfo?.hasNextPage&&wl?.pageInfo?.endCursor){
          after=wl.pageInfo.endCursor;
        }else{
          after=null;
        }

        if(pages>=20&&after){
          result.complete=false;
          result.errors.push('pagination '+String(friend.username||friend.id)+' limited to 20 pages');
          break;
        }
      }while(after);

      for(let i=0;i<rawItems.length;i+=8){
        const batch=rawItems.slice(i,i+8);
        const enriched=await Promise.allSettled(batch.map(item=>enrichFriendItem(friend,item)));

        for(const r of enriched){
          if(r.status==='fulfilled'){
            const type=String(r.value.type||'').toLowerCase();
            if(['movie','show'].includes(type)&&r.value.title) result.items.push(r.value);
          }else{
            result.complete=false;
            result.errors.push(String(friend.username||friend.id)+': '+r.reason.message);
          }
        }
      }
    }catch(e){
      result.complete=false;
      result.errors.push(String(friend.username||friend.id)+': '+e.message);
    }

    result.friends.push({
      id:String(friend.id||''),
      username:String(friend.username||''),
      count,
      pages
    });
  }

  return result;
}

function mergeItems(items){
  const map=new Map();

  for(const raw of items){
    const item=compact(raw);
    const key=keyOf(item);
    if(!key) continue;

    const previous=map.get(key);
    if(!previous){
      map.set(key,item);
      continue;
    }

    map.set(key,{
      ...previous,
      ...item,
      watchlistedAt:previous.watchlistedAt??item.watchlistedAt??null,
      guids:[...new Set([...(previous.guids||[]),...(item.guids||[])])],
      requestedBy:[...new Set([...(previous.requestedBy||[]),...(item.requestedBy||[])])]
    });
  }

  return [...map.values()];
}

(async()=>{
  const self=await getSelfWatchlist();

  let social;
  try{
    social=await getFriendsWatchlists();
  }catch(e){
    social={items:[],complete:false,friends:[],errors:[e.message]};
  }

  const current=mergeItems([...self.items,...social.items]);
  const complete=self.complete&&social.complete;

  const prev=readState();
  let pending=Array.isArray(prev.pendingRemoved)?prev.pendingRemoved.slice():[];
  let processItems=[];
  let nextCursor=Number(prev.processCursor||0);

  if(complete){
    const currentKeys=new Set(current.map(keyOf));
    const previousKeys=new Set((prev.current||[]).map(keyOf).filter(Boolean));
    const map=new Map(pending.map(x=>[keyOf(x),x]).filter(([k])=>Boolean(k)));

    if(prev.initialized){
      for(const old of prev.current){
        const k=keyOf(old);
        if(k&&!currentKeys.has(k)) map.set(k,compact(old));
      }
    }

    for(const cur of current) map.delete(keyOf(cur));
    pending=[...map.values()];

    const newItems=current.filter(x=>!previousKeys.has(keyOf(x)));

    const selectBatch=(rows,startIndex=0)=>{
      const selected=[];
      let seriesCount=0;
      let scanned=0;
      const total=rows.length;

      while(scanned<total && selected.length<MAX_PROCESS_PER_RUN){
        const idx=(startIndex+scanned)%total;
        const item=rows[idx];
        const isSeries=String(item?.type||'').toLowerCase()==='show';

        // Stop before a fourth series. The cursor will resume exactly on it
        // during the next workflow execution instead of skipping it.
        if(isSeries && seriesCount>=MAX_SERIES_PER_RUN) break;

        selected.push(item);
        if(isSeries) seriesCount++;
        scanned++;
      }

      return {selected,scanned};
    };

    if(newItems.length){
      const batch=selectBatch(newItems,0);
      processItems=batch.selected;
      // Continue from the position actually scanned, including series deferred
      // by the per-run concurrency cap.
      nextCursor=Math.min(batch.scanned,current.length);
    }else if(current.length){
      const start=((Number(prev.processCursor)||0)%current.length+current.length)%current.length;
      const batch=selectBatch(current,start);
      processItems=batch.selected;
      nextCursor=(start+batch.scanned)%current.length;
    }else{
      nextCursor=0;
    }

    writeState({
      version:3,
      initialized:true,
      updatedAt:new Date().toISOString(),
      source:'self+friends',
      current,
      pendingRemoved:pending,
      processCursor:nextCursor
    });
  }

  console.log(JSON.stringify({
    service:'plex-discover',
    mode:'multi-user-stateful-reconcile',
    complete,
    count:current.length,
    processCount:processItems.length,
    seriesProcessCount:processItems.filter(x=>String(x?.type||'').toLowerCase()==='show').length,
    maxSeriesPerRun:MAX_SERIES_PER_RUN,
    processCursor:nextCursor,
    selfCount:self.items.length,
    selfReportedTotal:self.total,
    friendCount:social.friends.length,
    friendItemCount:social.items.length,
    friends:social.friends,
    socialErrors:social.errors,
    initializedBefore:prev.initialized,
    pendingRemovedCount:complete?pending.length:prev.pendingRemoved.length,
    items:processItems,
    removed:complete?pending:[]
  }));
})().catch(e=>{
  console.error('Plex multi-user watchlist: '+e.message);
  process.exit(1);
});
NODE

parameters.jsCode:
const raw = String($input.first().json.stdout || '').trim();
let payload;
try { payload = JSON.parse(raw); }
catch (e) { throw new Error('Invalid Plex response: ' + e.message); }

const source = Array.isArray(payload.items) ? payload.items : [];
const removed = Array.isArray(payload.removed) ? payload.removed : [];
const output = [];
const dedup = new Set();
const nowIso = new Date().toISOString();

for (const src of source) {
  const type = String(src.type || '').toLowerCase();
  if (type !== 'movie' && type !== 'show') continue;

  const title = String(src.title || '').trim();
  if (!title) continue;

  const key = String(src.ratingKey || src.guid || (type + ':' + title + ':' + (src.year ?? ''))).trim();
  if (!key || dedup.has(key)) continue;
  dedup.add(key);

  const item = {
    key,
    type,
    title,
    year: src.year == null ? null : Number(src.year),
    ratingKey: String(src.ratingKey || ''),
    guid: String(src.guid || ''),
    guids: Array.isArray(src.guids) ? src.guids.map(String) : [],
    requestedBy: Array.isArray(src.requestedBy) ? src.requestedBy.map(String) : [],
    watchlistedAt: src.watchlistedAt ?? null,
    reconciledAt: nowIso
  };

  output.push({
    json: {
      ...item,
      _action: 'present',
      _payloadB64: Buffer.from(JSON.stringify(item), 'utf8').toString('base64')
    }
  });
}

if (payload.complete !== false && removed.length) {
  output.push({
    json: {
      _action: 'removed_batch',
      removedCount: removed.length,
      _payloadB64: Buffer.from(JSON.stringify(removed), 'utf8').toString('base64')
    }
  });
}

return output;

parameters.command:
=INPUT_B64='{{ $json._payloadB64 }}' node <<'NODE'
const fs=require('fs');
const path=require('path');
const input=JSON.parse(Buffer.from(String(process.env.INPUT_B64||''),'base64').toString('utf8'));
const cfg=JSON.parse(fs.readFileSync((process.env.SYNOPLEX_STACK_JSON||'/data/PlexMediaServer/stack.json'),'utf8'));
const BASE=String(cfg.radarr?.url||'').replace(/\/$/,'');
const API_KEY=String(cfg.radarr?.api_key||'').trim();
const ROOT=String(cfg.paths?.movies||'').replace(/\/$/,'');
const PROFILE=Number(cfg.radarr?.quality_profile_id||4);
const SEARCH_COOLDOWN_MS=60*60*1000;
const MIN_SEEDERS=10;
const VIDEO_EXT=new Set(['.mkv','.mp4','.avi','.m4v','.mov','.ts','.m2ts','.webm','.wmv']);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function api(p,options={},attempts=3){
  let last;
  for(let i=1;i<=attempts;i++){
    try{
      const r=await fetch(BASE+p,{...options,headers:{'X-Api-Key':API_KEY,'Accept':'application/json','Content-Type':'application/json',...(options.headers||{})},signal:AbortSignal.timeout(10000)});
      const txt=await r.text(); let data=null; try{data=txt?JSON.parse(txt):null}catch{data=txt}
      if(r.ok) return data;
      const retryable=r.status===429||r.status>=500;
      const e=new Error('HTTP '+r.status+' '+p+' :: '+String(txt).slice(0,300));
      if(!retryable||i===attempts) throw e; last=e;
    }catch(e){last=e;if(i===attempts) throw e;}
    await sleep(500*i);
  }
  throw last||new Error('Unknown Radarr API error');
}

async function grabMovieRelease(movieId){
  const [releases,clients]=await Promise.all([
    api('/api/v3/release?movieId='+encodeURIComponent(movieId)),
    api('/api/v3/downloadclient')
  ]);
  function isFrenchRelease(r){
    const title=String(r?.title||'');
    const explicitFrench=/\b(TRUEFRENCH|FRENCH|FRE|FR|VFF|VF2|VFI|VOF|VOSTFR|FRFR)\b/i.test(title);
    const multi=/\bMULTI\b/i.test(title);
    const vfq=/\bVFQ\b/i.test(title);
    const voOnly=/\bVO\b/i.test(title) && !/\bVOSTFR\b/i.test(title);
    const langs=Array.isArray(r?.languages)?r.languages:[];
    const frenchMetadata=langs.some(l=>{
      const value=String(l?.name||l?.language||l||'').toLowerCase();
      return value.includes('french')||value==='fr'||value==='fra';
    });
    return !vfq && !voOnly && (explicitFrench||(multi&&frenchMetadata));
  }
  const candidates=(Array.isArray(releases)?releases:[]).filter(r=>{
    const torrent=Boolean(r.magnetUrl||r.infoHash)||String(r.protocol||'').toLowerCase()==='torrent';
    const seeders=Number(r?.seeders??0);
    return torrent && seeders>MIN_SEEDERS && r.downloadAllowed!==false && r.rejected!==true && r.temporarilyRejected!==true && isFrenchRelease(r);
  });
  if(!candidates.length) return {grabbed:false,status:'NO_ACCEPTABLE_RELEASE'};
  const release=candidates[0];
  const isC411=Number(release?.indexerId)===21;
  const decy=(Array.isArray(clients)?clients:[]).find(c=>String(c.name||'').toLowerCase()==='decypharr'&&c.enable!==false);
  const qbit=(Array.isArray(clients)?clients:[]).find(c=>{
    const impl=String(c.implementation||'').toLowerCase();
    return impl==='qbittorrent'&&String(c.name||'').toLowerCase()!=='decypharr'&&c.enable!==false;
  });
  if(!decy&&!qbit) return {grabbed:false,status:'NO_DOWNLOAD_CLIENT'};
  async function grab(client){
    const response=await fetch(BASE+'/api/v3/release',{
      method:'POST',
      headers:{'X-Api-Key':API_KEY,'Accept':'application/json','Content-Type':'application/json'},
      body:JSON.stringify({...release,downloadClientId:Number(client.id)}),
      signal:AbortSignal.timeout(20000)
    });
    const text=await response.text();
    let data=null; try{data=text?JSON.parse(text):null}catch{data=text}
    return {ok:response.ok,status:response.status,data,text};
  }
  if(isC411){
    if(!qbit) return {grabbed:false,status:'C411_QBIT_REQUIRED',releaseTitle:release.title,releaseIndexerId:release.indexerId,indexer:'C411'};
    const c411Grab=await grab(qbit);
    if(c411Grab.ok) return {grabbed:true,status:'GRABBED_C411_QBIT',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:false,keepSeeding:true,indexer:'C411',releaseIndexerId:release.indexerId,releaseTitle:release.title};
    return {grabbed:false,status:'C411_QBIT_FAILED',qbittorrentStatus:c411Grab.status,error:String(c411Grab.text||'').slice(0,300),indexer:'C411',releaseIndexerId:release.indexerId,releaseTitle:release.title};
  }
  if(decy){
    const first=await grab(decy);
    if(first.ok) return {grabbed:true,status:'GRABBED',downloadClient:'Decypharr',downloadClientId:decy.id,fallbackUsed:false,releaseTitle:release.title};
    if((first.status===400||first.status===409)&&qbit){
      const fallback=await grab(qbit);
      if(fallback.ok) return {grabbed:true,status:'GRABBED_FALLBACK',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:true,decypharrStatus:first.status,releaseTitle:release.title};
      return {grabbed:false,status:'FALLBACK_FAILED',decypharrStatus:first.status,qbittorrentStatus:fallback.status,error:String(fallback.text||'').slice(0,300),releaseTitle:release.title};
    }
    return {grabbed:false,status:'DECYPHARR_FAILED_NO_FALLBACK',decypharrStatus:first.status,error:String(first.text||'').slice(0,300),releaseTitle:release.title};
  }
  const fallback=await grab(qbit);
  return fallback.ok
    ? {grabbed:true,status:'GRABBED_QBIT_ONLY',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:true,releaseTitle:release.title}
    : {grabbed:false,status:'QBIT_FAILED',qbittorrentStatus:fallback.status,error:String(fallback.text||'').slice(0,300),releaseTitle:release.title};
}

function extractGuid(prefix){
  for(const value of (Array.isArray(input.guids)?input.guids:[])){
    const m=String(value).match(new RegExp('^'+prefix+':\\/\\/(\\d+)$','i'));
    if(m) return Number(m[1]);
  }
  return null;
}
function normLookupTitle(s){
  return String(s||'')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,' ')
    .trim()
    .replace(/\s+/g,' ');
}
function titleMatchesInput(row){
  const target=normLookupTitle(input.title);
  if(!target) return false;
  const titles=[
    row?.title,
    row?.originalTitle,
    ...(Array.isArray(row?.alternateTitles)?row.alternateTitles.map(a=>a?.title):[])
  ];
  return titles.some(t=>normLookupTitle(t)===target);
}
function pathMappings(){
  return [
    [String(cfg.paths?.config_root||''),String(cfg.paths?.n8n_config_root||'')],
    [String(cfg.paths?.media_root||''),String(cfg.paths?.n8n_media_root||'')]
  ].filter(([nasRoot,localRoot])=>nasRoot&&localRoot)
   .sort((a,b)=>b[0].length-a[0].length);
}
function canMapNas(nasPath){
  const p=String(nasPath||'');
  return pathMappings().some(([nasRoot])=>p===nasRoot||p.startsWith(nasRoot+'/'));
}
function localPath(nasPath){
  const p=String(nasPath||'');
  for(const [nasRoot,localRoot] of pathMappings()){
    if(p===nasRoot||p.startsWith(nasRoot+'/')) return localRoot+p.slice(nasRoot.length);
  }
  throw new Error('No n8n path mapping for NAS path: '+p);
}
function localToNas(local){
  const p=String(local||'');
  for(const [nasRoot,localRoot] of pathMappings()){
    if(p===localRoot||p.startsWith(localRoot+'/')) return nasRoot+p.slice(localRoot.length);
  }
  throw new Error('No NAS path mapping for n8n path: '+p);
}
function hasVideo(dir){
  if(!fs.existsSync(dir)) return false;
  const st=fs.statSync(dir);
  if(st.isFile()) return VIDEO_EXT.has(path.extname(dir).toLowerCase());
  for(const name of fs.readdirSync(dir)){
    const p=path.join(dir,name); const s=fs.statSync(p);
    if(s.isDirectory()){ if(hasVideo(p)) return true; }
    else if(s.isFile()&&VIDEO_EXT.has(path.extname(name).toLowerCase())) return true;
  }
  return false;
}
async function waitCommand(id){
  if(!id) return null;
  for(let i=0;i<20;i++){
    const c=await api('/api/v3/command/'+id);
    const status=String(c?.status||'').toLowerCase();
    if(['completed','failed','aborted'].includes(status)) return c;
    await sleep(500);
  }
  return null;
}
(async()=>{
  if(input.type!=='movie') throw new Error('Unexpected Plex type for Radarr: '+input.type);
  if(!BASE||!API_KEY) throw new Error('Incomplete Radarr configuration');
  const [profile,roots]=await Promise.all([api('/api/v3/qualityprofile/'+PROFILE),api('/api/v3/rootfolder')]);
  if(!profile||Number(profile.id)!==PROFILE) throw new Error('Radarr quality profile ID '+PROFILE+' not found');
  let root=Array.isArray(roots)?roots.find(x=>String(x.path||'').replace(/\/$/,'')===ROOT):null;
  if(!root) root=await api('/api/v3/rootfolder',{method:'POST',body:JSON.stringify({path:ROOT})});
  if(!root?.id) throw new Error('Radarr root folder unavailable: '+ROOT);

  const tmdbFromPlex=extractGuid('tmdb');
  let hit=null, existing=[];
  if(tmdbFromPlex){
    existing=await api('/api/v3/movie?tmdbId='+encodeURIComponent(tmdbFromPlex));
    if(!Array.isArray(existing)) existing=[];
    if(!existing.length){
      const lookup=await api('/api/v3/movie/lookup?term='+encodeURIComponent('tmdb:'+tmdbFromPlex));
      hit=Array.isArray(lookup)?lookup[0]||null:null;
    }
  }else{
    const term=[input.title,input.year||''].join(' ').trim();
    const lookup=await api('/api/v3/movie/lookup?term='+encodeURIComponent(term));
    const rows=Array.isArray(lookup)?lookup:[];
    const hasYear=Number.isFinite(Number(input.year))&&Number(input.year)>0;
    hit=rows.find(x=>titleMatchesInput(x)&&(!hasYear||Number(x.year)===Number(input.year)))||null;
    if(hit?.tmdbId){ existing=await api('/api/v3/movie?tmdbId='+encodeURIComponent(hit.tmdbId)); if(!Array.isArray(existing)) existing=[]; }
  }

  if(existing.length){
    let movie=existing[0];
    if(!movie?.id) throw new Error('Existing Radarr movie has no internal ID');

    const wasMonitored=Boolean(movie.monitored);
    const profileChanged=Number(movie.qualityProfileId)!==PROFILE;
    if(!movie.monitored||profileChanged){
      movie.monitored=true;
      movie.qualityProfileId=PROFILE;
      movie=await api('/api/v3/movie/'+movie.id,{method:'PUT',body:JSON.stringify(movie)});
    }

    // Decypharr imports can be absolute symlinks that Plex/Radarr can read on
    // the NAS but that are intentionally not dereferenceable through n8n's
    // SMB mount. Radarr is therefore the source of truth for file presence.
    if(movie.hasFile){
      console.log(JSON.stringify({
        ok:true,key:input.key,type:input.type,service:'radarr',
        action:'arr_file_present',
        title:movie.title||input.title,year:movie.year||input.year,
        radarrId:movie.id,monitored:Boolean(movie.monitored),
        wasMonitored,qualityProfileId:movie.qualityProfileId,profileChanged,
        hasFile:true,arrManaged:true,localFsCheckSkipped:true,
        searchTriggered:false
      }));
      return;
    }

    const [queue,commands]=await Promise.all([api('/api/v3/queue?page=1&pageSize=100&includeUnknownMovieItems=true'),api('/api/v3/command')]);
    const activeDownload=(queue?.records||[]).some(x=>Number(x.movieId)===Number(movie.id));
    const activeSearch=(Array.isArray(commands)?commands:[]).some(c=>{
      const status=String(c.status||'').toLowerCase();
      const name=String(c.name||'').toLowerCase();
      const ids=Array.isArray(c.body?.movieIds)?c.body.movieIds.map(Number):[];
      return ['queued','started'].includes(status)&&name.includes('moviessearch')&&(!ids.length||ids.includes(Number(movie.id)));
    });
    const lastSearchMs=Date.parse(movie.lastSearchTime||'');
    const searchDue=!Number.isFinite(lastSearchMs)||(Date.now()-lastSearchMs)>=SEARCH_COOLDOWN_MS;
    let searchTriggered=false, commandId=null, route=null;
    if(!activeDownload&&!activeSearch&&searchDue){
      route=await grabMovieRelease(movie.id);
      searchTriggered=Boolean(route?.grabbed);
      commandId=route?.downloadClientId??null;
    }

    console.log(JSON.stringify({ok:true,key:input.key,type:input.type,service:'radarr',action:searchTriggered?'missing_grabbed':'missing_monitored',title:movie.title||input.title,year:movie.year||input.year,radarrId:movie.id,monitored:Boolean(movie.monitored),wasMonitored,qualityProfileId:movie.qualityProfileId,profileChanged,hasFile:Boolean(movie.hasFile),mediaPresent:false,activeDownload,activeSearch,searchDue,searchTriggered,commandId,lastSearchTime:movie.lastSearchTime||null,route}));
    return;
  }

  if(!hit?.tmdbId){
    console.log(JSON.stringify({ok:true,key:input.key,type:input.type,service:'radarr',action:'not_found',title:input.title,year:input.year,searchTriggered:false}));
    return;
  }

  const created=await api('/api/v3/movie',{method:'POST',body:JSON.stringify({...hit,qualityProfileId:PROFILE,rootFolderPath:ROOT,monitored:true,tags:[],addOptions:{searchForMovie:false}})});
  if(!created?.id) throw new Error('Radarr added the movie without returning an internal ID');
  const route=await grabMovieRelease(created.id);
  console.log(JSON.stringify({ok:true,key:input.key,type:input.type,service:'radarr',action:route?.grabbed?'added_grabbed':'added_monitored',title:created.title||hit.title||input.title,year:created.year||hit.year||input.year,radarrId:created.id,tmdbId:created.tmdbId||hit.tmdbId,monitored:Boolean(created.monitored),hasFile:Boolean(created.hasFile),mediaPresent:false,searchTriggered:Boolean(route?.grabbed),route}));
})().catch(e=>console.log(JSON.stringify({ok:false,key:input.key,type:input.type,service:'radarr',action:'error',title:input.title,year:input.year,error:e.message})));
