const fs=require('fs');
const path=require('path');
const input=JSON.parse(Buffer.from(String(process.env.INPUT_B64||''),'base64').toString('utf8'));
const cfg=JSON.parse(fs.readFileSync((process.env.SYNOPLEX_STACK_JSON||'/data/PlexMediaServer/stack.json'),'utf8'));
const BASE=String(cfg.sonarr?.url||'').replace(/\/$/,'');
const API_KEY=String(cfg.sonarr?.api_key||'').trim();
const PROWLARR_BASE=String(cfg.prowlarr?.url||'').replace(/\/$/,'');
const PROWLARR_KEY=String(cfg.prowlarr?.api_key||'').trim();
const QBIT_BASE=String(cfg.qbittorrent?.url||'').replace(/\/$/,'');
const QBIT_USER=String(cfg.qbittorrent?.username||'').trim();
const QBIT_PASS=String(cfg.qbittorrent?.password||'');
const ROOT=String(cfg.paths?.series||'').replace(/\/$/,'');
const PROFILE=Number(cfg.sonarr?.quality_profile_id||4);
const MIN_SEEDERS=10;
const SEARCH_COOLDOWN_MS=60*60*1000;
const SEARCH_NO_RESULT_COOLDOWN_MS=15*60*1000;
const GLOBAL_SEARCH_INTERVAL_MS=0;
const RELEASE_SEARCH_TIMEOUT_MS=120000;
const GLOBAL_SEARCH_KEY='__global';
const SEARCH_STATE='/data/PlexMediaServer/sonarr-search-state.json';
const SEARCH_LOCK='/home/node/.n8n/.sonarr-release-search.lock';

function readSearchState(){
  try{
    const x=JSON.parse(fs.readFileSync(SEARCH_STATE,'utf8'));
    return x&&typeof x==='object'?x:{};
  }catch{return {};}
}
function writeSearchState(state){
  const tmp=SEARCH_STATE+'.tmp-'+process.pid;
  fs.writeFileSync(tmp,JSON.stringify(state,null,2));
  fs.renameSync(tmp,SEARCH_STATE);
}
async function acquireSearchLock(timeoutMs=120000){
  const started=Date.now();
  while(Date.now()-started<timeoutMs){
    try{
      try{
        const st=fs.statSync(SEARCH_LOCK);
        if(Date.now()-st.mtimeMs>15*60*1000) fs.unlinkSync(SEARCH_LOCK);
      }catch{}
      const fd=fs.openSync(SEARCH_LOCK,'wx');
      return ()=>{
        try{fs.closeSync(fd)}catch{}
        try{fs.unlinkSync(SEARCH_LOCK)}catch{}
      };
    }catch(e){
      if(e?.code!=='EEXIST') throw e;
      await sleep(500);
    }
  }
  throw new Error('SONARR_SEARCH_LOCK_TIMEOUT');
}
const VIDEO_EXT=new Set(['.mkv','.mp4','.avi','.m4v','.mov','.ts','.m2ts','.webm','.wmv']);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function api(p,options={},attempts=3){
  let last;
  for(let i=1;i<=attempts;i++){
    try{
      const r=await fetch(BASE+p,{...options,headers:{'X-Api-Key':API_KEY,'Accept':'application/json','Content-Type':'application/json',...(options.headers||{})},signal:AbortSignal.timeout(10000)});
      const txt=await r.text(); let data=null; try{data=txt?JSON.parse(txt):null}catch{data=txt}
      if(r.ok) return data;
      const retryable=r.status===429||r.status>=500;
      const e=new Error('HTTP '+r.status+' '+p+' :: '+String(txt).slice(0,300));
      if(!retryable||i===attempts) throw e; last=e;
    }catch(e){last=e;if(i===attempts) throw e;}
    await sleep(500*i);
  }
  throw last||new Error('Unknown Sonarr API error');
}

async function searchEpisodeReleases(episodeId){
  const p='/api/v3/release?episodeId='+encodeURIComponent(episodeId);
  let r;
  try{
    r=await fetch(BASE+p,{
      headers:{'X-Api-Key':API_KEY,'Accept':'application/json','Content-Type':'application/json'},
      signal:AbortSignal.timeout(RELEASE_SEARCH_TIMEOUT_MS)
    });
  }catch(e){
    const msg=String(e?.message||e||'Unknown error');
    throw new Error('SONARR_RELEASE_SEARCH_FAILED episodeId='+episodeId+' :: '+msg);
  }
  const txt=await r.text();
  let data=null; try{data=txt?JSON.parse(txt):null}catch{data=txt}
  if(!r.ok) throw new Error('SONARR_RELEASE_SEARCH_HTTP_'+r.status+' episodeId='+episodeId+' :: '+String(txt).slice(0,300));
  return data;
}

async function controlledC411SeasonSearch(seriesId,seasonNumber,clients){
  if(!PROWLARR_BASE||!PROWLARR_KEY||!QBIT_BASE||!QBIT_USER||!QBIT_PASS){
    return {grabbed:false,status:'C411_PRIMARY_CONFIG_MISSING',seasonNumber:Number(seasonNumber)};
  }

  const series=await api('/api/v3/series/'+encodeURIComponent(seriesId));
  if(!series?.title){
    return {grabbed:false,status:'C411_PRIMARY_SERIES_NOT_FOUND',seasonNumber:Number(seasonNumber)};
  }

  async function prowlarr(p,options={},timeoutMs=60000){
    const r=await fetch(PROWLARR_BASE+p,{
      ...options,
      headers:{
        'X-Api-Key':PROWLARR_KEY,
        'Accept':'application/json',
        'Content-Type':'application/json',
        ...(options.headers||{})
      },
      signal:AbortSignal.timeout(timeoutMs)
    });
    const txt=await r.text();
    let data=null; try{data=txt?JSON.parse(txt):null}catch{data=txt}
    if(!r.ok) throw new Error('PROWLARR_HTTP_'+r.status+' '+p+' :: '+String(txt).slice(0,300));
    return data;
  }

  async function qbitLogin(){
    const r=await fetch(QBIT_BASE+'/api/v2/auth/login',{
      method:'POST',
      headers:{
        'Content-Type':'application/x-www-form-urlencoded',
        'Referer':QBIT_BASE+'/'
      },
      body:new URLSearchParams({username:QBIT_USER,password:QBIT_PASS}),
      signal:AbortSignal.timeout(7000)
    });
    const txt=(await r.text()).trim();
    const cookie=(r.headers.get('set-cookie')||'').split(';',1)[0];
    if(!r.ok||txt==='Fails.') throw new Error('QBIT_AUTH_FAILED');
    return cookie;
  }

  async function qbit(cookie,p,options={}){
    const r=await fetch(QBIT_BASE+p,{
      ...options,
      headers:{'Referer':QBIT_BASE+'/',Cookie:cookie,...(options.headers||{})},
      signal:AbortSignal.timeout(15000)
    });
    const txt=await r.text();
    let data=null; try{data=txt?JSON.parse(txt):null}catch{data=txt}
    if(!r.ok) throw new Error('QBIT_HTTP_'+r.status+' '+p+' :: '+String(txt).slice(0,300));
    return data;
  }

  function explicitYearMismatch(title){
    const expected=Number(series.year||0);
    if(!expected) return false;
    const years=[...String(title||'').matchAll(/\b((?:19|20)\d{2})\b/g)].map(m=>Number(m[1]));
    return years.length>0&&!years.some(y=>Math.abs(y-expected)<=1);
  }

  function seasonSpecific(title){
    const n=Number(seasonNumber);
    if(!Number.isFinite(n)||n<=0) return false;
    const re=new RegExp('\\bS0*'+n+'\\b','i');
    return re.test(String(title||''));
  }

  function integral(title){
    return /\b(INTEGRALE|COMPLETE|COMPLETE[._ -]?SERIES|FULL[._ -]?SERIES)\b/i.test(String(title||''));
  }

  function languageScore(title){
    const t=String(title||'');
    if(/\b(VFF|VF2)\b/i.test(t)) return 4;
    if(/\b(TRUEFRENCH|FRENCH)\b/i.test(t)) return 3;
    if(/\bMULTI\b/i.test(t)) return 2;
    if(/\bVOSTFR\b/i.test(t)) return 1;
    return 0;
  }

  function qualityScore(title){
    const t=String(title||'');
    if(/2160p/i.test(t)) return 4;
    if(/1080p/i.test(t)) return 3;
    if(/720p/i.test(t)) return 2;
    if(/576p|480p|DVDRip/i.test(t)) return 1;
    return 0;
  }

  try{
    const indexers=await prowlarr('/api/v1/indexer',{},15000);
    const c411=(Array.isArray(indexers)?indexers:[]).find(x=>/^C411\b/i.test(String(x.name||'')));
    if(!c411){
      return {grabbed:false,status:'C411_PRIMARY_UNAVAILABLE',seasonNumber:Number(seasonNumber)};
    }

    // C411 definition enforces ~15 requests/minute. One broad query is enough:
    // it reliably exposes season packs that Sonarr's structured tvsearch can miss.
    await sleep(4300);
    const releases=await prowlarr(
      '/api/v1/search?query='+encodeURIComponent(series.title)+
      '&type=search&indexerIds='+encodeURIComponent(c411.id)+
      '&limit=100&offset=0',
      {},
      60000
    );

    const baseCandidates=(Array.isArray(releases)?releases:[]).filter(r=>{
      const title=String(r?.title||'');
      const torrent=String(r?.protocol||'').toLowerCase()==='torrent'||Boolean(r?.magnetUrl||r?.infoHash);
      return torrent
        && Boolean(r?.downloadUrl||r?.magnetUrl)
        && Number(r?.seeders??0)>MIN_SEEDERS
        && !explicitYearMismatch(title)
        && !/\bVFQ\b/i.test(title)
        && languageScore(title)>0;
    });

    const exactSeason=baseCandidates.filter(r=>seasonSpecific(r.title));
    const integralCandidates=baseCandidates.filter(r=>integral(r.title));
    const pool=integralCandidates.length?integralCandidates:exactSeason;
    const selectedScope=integralCandidates.length?'INTEGRAL':'SEASON_PACK';

    if(!pool.length){
      return {
        grabbed:false,
        status:'C411_PRIMARY_NO_GRAB',
        seasonNumber:Number(seasonNumber),
        releaseIndexerId:c411.id,
        searchScope:'C411_BROAD',
        candidateCount:baseCandidates.length
      };
    }

    pool.sort((a,b)=>{
      const langDiff=languageScore(b.title)-languageScore(a.title);
      if(langDiff) return langDiff;
      const qualityDiff=qualityScore(b.title)-qualityScore(a.title);
      if(qualityDiff) return qualityDiff;
      return Number(b?.seeders??0)-Number(a?.seeders??0);
    });

    const release=pool[0];
    const cookie=await qbitLogin();
    const existing=await qbit(cookie,'/api/v2/torrents/info?category=sonarr');
    const byHash=String(release?.infoHash||'').toLowerCase();
    const duplicate=(Array.isArray(existing)?existing:[]).find(t=>
      (byHash&&String(t?.hash||'').toLowerCase()===byHash) ||
      String(t?.name||'').toLowerCase()===String(release?.title||'').toLowerCase()
    );

    if(duplicate){
      return {
        grabbed:true,
        status:'C411_PRIMARY_ALREADY_IN_QBIT',
        routeStage:'PRIMARY_C411',
        searchScope:'C411_BROAD',
        seasonNumber:Number(seasonNumber),
        releaseTitle:release.title,
        downloadId:duplicate.hash||null,
        downloadClient:'qBittorrent',
        fallbackUsed:false,
        keepSeeding:true,
        indexer:'C411',
        releaseIndexerId:c411.id,
        seeders:Number(release?.seeders??0)
      };
    }

    const url=String(release?.downloadUrl||release?.magnetUrl||'');
    const body=new URLSearchParams({
      urls:url,
      category:'sonarr',
      tags:'seed-c411'
    });
    await qbit(cookie,'/api/v2/torrents/add',{
      method:'POST',
      headers:{'Content-Type':'application/x-www-form-urlencoded'},
      body
    });

    // Give qBittorrent a moment to materialize the job and return its hash.
    await sleep(1500);
    const after=await qbit(cookie,'/api/v2/torrents/info?category=sonarr');
    const added=(Array.isArray(after)?after:[]).find(t=>
      (byHash&&String(t?.hash||'').toLowerCase()===byHash) ||
      String(t?.name||'').toLowerCase()===String(release?.title||'').toLowerCase()
    )||null;

    return {
      grabbed:true,
      status:'GRABBED_C411_PRIMARY_QBIT',
      routeStage:'PRIMARY_C411',
      searchScope:'C411_BROAD',
      seasonNumber:Number(seasonNumber),
      releaseTitle:release.title,
      downloadId:added?.hash||release?.infoHash||null,
      downloadClient:'qBittorrent',
      fallbackUsed:false,
      keepSeeding:true,
      indexer:'C411',
      releaseIndexerId:c411.id,
      seeders:Number(release?.seeders??0),
      exactSeason:Boolean(exactSeason.length)
    };
  }catch(e){
    return {
      grabbed:false,
      status:'C411_PRIMARY_ERROR',
      seasonNumber:Number(seasonNumber),
      searchScope:'C411_BROAD',
      error:String(e?.message||e||'Unknown C411 primary error').slice(0,500)
    };
  }
}

function isFrenchRelease(r){
  const title=String(r?.title||'');
  const explicitFrench=/\b(TRUEFRENCH|FRENCH|FRE|FR|VFF|VF2|VFI|VOF|VOSTFR|FRFR)\b/i.test(title);
  const multi=/\bMULTI\b/i.test(title);
  const vfq=/\bVFQ\b/i.test(title);
  const voOnly=/\bVO\b/i.test(title) && !/\bVOSTFR\b/i.test(title);
  const langs=Array.isArray(r?.languages)?r.languages:[];
  const frenchMetadata=langs.some(l=>{
    const value=String(l?.name||l?.language||l||'').toLowerCase();
    return value.includes('french')||value==='fr'||value==='fra';
  });
  return !vfq && !voOnly && (explicitFrench||(multi&&frenchMetadata));
}

async function grabNextSeriesRelease(seriesId){
  const [episodes,clients]=await Promise.all([
    api('/api/v3/episode?seriesId='+encodeURIComponent(seriesId)),
    api('/api/v3/downloadclient')
  ]);
  const now=Date.now();
  const missing=(Array.isArray(episodes)?episodes:[])
    .filter(e=>Number(e.seasonNumber||0)>0&&e.monitored!==false&&!e.hasFile&&(!e.airDateUtc||Date.parse(e.airDateUtc)<=now))
    .sort((a,b)=>(Date.parse(a.airDateUtc||0)||0)-(Date.parse(b.airDateUtc||0)||0));
  if(!missing.length) return {grabbed:false,status:'NO_MISSING_AIRED_EPISODE'};

  const episode=missing[0];

  // Stage 1: C411 only, routed to qBittorrent.
  const c411Primary=await controlledC411SeasonSearch(seriesId,episode.seasonNumber,clients);
  if(c411Primary?.grabbed){
    return {
      ...c411Primary,
      episodeId:episode.id,
      episodeNumber:episode.episodeNumber,
      episodeTitle:episode.title
    };
  }

  // Stage 2: only if C411 did not grab anything, search all interactive indexers.
  const releases=await searchEpisodeReleases(episode.id);
  // Sonarr release.indexerId is Sonarr-local, never Prowlarr's indexer ID.
  const sonarrIndexerRows=await api('/api/v3/indexer').catch(()=>[]);
  const c411IndexerId=Number((Array.isArray(sonarrIndexerRows)?sonarrIndexerRows:[]).find(x=>/\bC411\b/i.test(String(x.name||'')))?.id||0);
  const candidates=(Array.isArray(releases)?releases:[]).filter(r=>{
    const torrent=Boolean(r.magnetUrl||r.infoHash)||String(r.protocol||'').toLowerCase()==='torrent';
    const seeders=Number(r?.seeders??0);
    return torrent && seeders>MIN_SEEDERS && r.downloadAllowed!==false && r.rejected!==true && r.temporarilyRejected!==true && isFrenchRelease(r);
  }).sort((a,b)=>{
    const aC411=c411IndexerId&&Number(a?.indexerId)===c411IndexerId?1:0;
    const bC411=c411IndexerId&&Number(b?.indexerId)===c411IndexerId?1:0;
    if(aC411!==bC411) return bC411-aC411;
    return Number(b?.seeders??0)-Number(a?.seeders??0);
  });

  if(!candidates.length){
    return {
      grabbed:false,
      status:'NO_ACCEPTABLE_RELEASE',
      routeStage:'FALLBACK_GENERAL',
      episodeId:episode.id,
      seasonNumber:episode.seasonNumber,
      episodeNumber:episode.episodeNumber,
      episodeTitle:episode.title,
      c411Primary
    };
  }

  const release=candidates[0];
  const isC411=(Boolean(c411IndexerId)&&Number(release?.indexerId)===c411IndexerId)||/\bC411\b/i.test(String(release?.indexer||''));
  const decy=(Array.isArray(clients)?clients:[]).find(c=>String(c.name||'').toLowerCase()==='decypharr'&&c.enable!==false);
  const qbit=(Array.isArray(clients)?clients:[]).find(c=>{
    const impl=String(c.implementation||'').toLowerCase();
    return impl==='qbittorrent'&&String(c.name||'').toLowerCase()!=='decypharr'&&c.enable!==false;
  });
  if(!decy&&!qbit) return {grabbed:false,status:'NO_DOWNLOAD_CLIENT',episodeId:episode.id,c411Primary};

  async function grab(client){
    const response=await fetch(BASE+'/api/v3/release',{
      method:'POST',
      headers:{'X-Api-Key':API_KEY,'Accept':'application/json','Content-Type':'application/json'},
      body:JSON.stringify({...release,downloadClientId:Number(client.id)}),
      signal:AbortSignal.timeout(20000)
    });
    const text=await response.text();
    let data=null; try{data=text?JSON.parse(text):null}catch{data=text}
    return {ok:response.ok,status:response.status,data,text};
  }

  const episodeInfo={
    episodeId:episode.id,
    seasonNumber:episode.seasonNumber,
    episodeNumber:episode.episodeNumber,
    episodeTitle:episode.title,
    releaseTitle:release.title,
    routeStage:'FALLBACK_GENERAL',
    c411Primary
  };

  // Even during the general fallback, any C411 result still goes to qBittorrent.
  if(isC411){
    if(!qbit) return {...episodeInfo,grabbed:false,status:'C411_QBIT_REQUIRED',releaseIndexerId:release.indexerId,indexer:'C411'};
    const c411Grab=await grab(qbit);
    if(c411Grab.ok) return {...episodeInfo,grabbed:true,status:'GRABBED_C411_QBIT',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:true,keepSeeding:true,indexer:'C411',releaseIndexerId:release.indexerId};
    return {...episodeInfo,grabbed:false,status:'C411_QBIT_FAILED',qbittorrentStatus:c411Grab.status,error:String(c411Grab.text||'').slice(0,300),indexer:'C411',releaseIndexerId:release.indexerId};
  }

  // Non-C411 releases prefer Decypharr, with qBittorrent only as fallback.
  if(decy){
    const first=await grab(decy);
    if(first.ok) return {...episodeInfo,grabbed:true,status:'GRABBED',downloadClient:'Decypharr',downloadClientId:decy.id,fallbackUsed:true};
    if((first.status===400||first.status===409)&&qbit){
      const fallback=await grab(qbit);
      if(fallback.ok) return {...episodeInfo,grabbed:true,status:'GRABBED_FALLBACK',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:true,decypharrStatus:first.status};
      return {...episodeInfo,grabbed:false,status:'FALLBACK_FAILED',decypharrStatus:first.status,qbittorrentStatus:fallback.status,error:String(fallback.text||'').slice(0,300)};
    }
    return {...episodeInfo,grabbed:false,status:'DECYPHARR_FAILED_NO_FALLBACK',decypharrStatus:first.status,error:String(first.text||'').slice(0,300)};
  }

  const fallback=await grab(qbit);
  return fallback.ok
    ? {...episodeInfo,grabbed:true,status:'GRABBED_QBIT_ONLY',downloadClient:qbit.name||'qBittorrent',downloadClientId:qbit.id,fallbackUsed:true}
    : {...episodeInfo,grabbed:false,status:'QBIT_FAILED',qbittorrentStatus:fallback.status,error:String(fallback.text||'').slice(0,300)};
}

function extractGuid(prefix){
  for(const value of (Array.isArray(input.guids)?input.guids:[])){
    const m=String(value).match(new RegExp('^'+prefix+':\\/\\/(\\d+)$','i'));
    if(m) return Number(m[1]);
  }
  return null;
}
function normTitle(s){
  return String(s||'')
    .replace(/\s*\((19|20)\d{2}\)\s*$/,'')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/&/g,' and ')
    .replace(/[^a-z0-9]+/g,' ')
    .trim()
    .replace(/\s+/g,' ');
}
function titleMatchesInput(row){
  const wanted=normTitle(input.title);
  if(!wanted) return false;
  const candidates=[
    row?.title,
    row?.sortTitle,
    ...(Array.isArray(row?.alternateTitles)?row.alternateTitles.map(x=>x?.title):[])
  ].filter(Boolean).map(normTitle);
  return candidates.includes(wanted);
}
function yearMatchesInput(row){
  if(input.year==null||input.year==='') return true;
  const wanted=Number(input.year);
  const actual=Number(row?.year);
  if(!Number.isFinite(wanted)||!Number.isFinite(actual)) return false;
  return Math.abs(actual-wanted)<=1;
}
function pathMappings(){
  return [
    [String(cfg.paths?.config_root||''),String(cfg.paths?.n8n_config_root||'')],
    [String(cfg.paths?.media_root||''),String(cfg.paths?.n8n_media_root||'')]
  ].filter(([nasRoot,localRoot])=>nasRoot&&localRoot)
   .sort((a,b)=>b[0].length-a[0].length);
}
function canMapNas(nasPath){
  const p=String(nasPath||'');
  return pathMappings().some(([nasRoot])=>p===nasRoot||p.startsWith(nasRoot+'/'));
}
function localPath(nasPath){
  const p=String(nasPath||'');
  for(const [nasRoot,localRoot] of pathMappings()){
    if(p===nasRoot||p.startsWith(nasRoot+'/')) return localRoot+p.slice(nasRoot.length);
  }
  throw new Error('No n8n path mapping for NAS path: '+p);
}
function localToNas(local){
  const p=String(local||'');
  for(const [nasRoot,localRoot] of pathMappings()){
    if(p===localRoot||p.startsWith(localRoot+'/')) return nasRoot+p.slice(localRoot.length);
  }
  throw new Error('No NAS path mapping for n8n path: '+p);
}
function hasVideo(dir){
  if(!fs.existsSync(dir)) return false;
  const st=fs.statSync(dir);
  if(st.isFile()) return VIDEO_EXT.has(path.extname(dir).toLowerCase());
  for(const name of fs.readdirSync(dir)){
    const p=path.join(dir,name); const s=fs.statSync(p);
    if(s.isDirectory()){ if(hasVideo(p)) return true; }
    else if(s.isFile()&&VIDEO_EXT.has(path.extname(name).toLowerCase())) return true;
  }
  return false;
}
(async()=>{
  if(input.type!=='show') throw new Error('Unexpected Plex type for Sonarr: '+input.type);
  if(!BASE||!API_KEY) throw new Error('Incomplete Sonarr configuration');
  const [profile,roots]=await Promise.all([api('/api/v3/qualityprofile/'+PROFILE),api('/api/v3/rootfolder')]);
  if(!profile||Number(profile.id)!==PROFILE) throw new Error('Sonarr quality profile ID '+PROFILE+' not found');
  let root=Array.isArray(roots)?roots.find(x=>String(x.path||'').replace(/\/$/,'')===ROOT):null;
  if(!root) root=await api('/api/v3/rootfolder',{method:'POST',body:JSON.stringify({path:ROOT})});
  if(!root?.id) throw new Error('Sonarr root folder unavailable: '+ROOT);

  const tvdbFromPlex=extractGuid('tvdb');
  let hit=null, existing=[];
  if(tvdbFromPlex){
    existing=await api('/api/v3/series?tvdbId='+encodeURIComponent(tvdbFromPlex));
    if(!Array.isArray(existing)) existing=[];
    if(!existing.length){
      const lookup=await api('/api/v3/series/lookup?term='+encodeURIComponent('tvdb:'+tvdbFromPlex));
      const rows=Array.isArray(lookup)?lookup:[];
      hit=rows.find(x=>Number(x.tvdbId)===Number(tvdbFromPlex))||null;
    }
  }else{
    const lookup=await api('/api/v3/series/lookup?term='+encodeURIComponent(String(input.title||'').trim()));
    const rows=Array.isArray(lookup)?lookup:[];
    const strict=rows.filter(x=>titleMatchesInput(x)&&yearMatchesInput(x));

    if(strict.length===1){
      hit=strict[0];
    }else if(strict.length>1){
      const uniqueTvdb=[...new Set(strict.map(x=>Number(x.tvdbId)).filter(Boolean))];
      if(uniqueTvdb.length===1) hit=strict[0];
      else{
        console.log(JSON.stringify({
          ok:true,key:input.key,type:input.type,service:'sonarr',
          action:'ambiguous_match_rejected',title:input.title,year:input.year,
          candidates:strict.slice(0,10).map(x=>({title:x.title,year:x.year,tvdbId:x.tvdbId})),
          searchTriggered:false
        }));
        return;
      }
    }

    if(hit?.tvdbId){
      existing=await api('/api/v3/series?tvdbId='+encodeURIComponent(hit.tvdbId));
      if(!Array.isArray(existing)) existing=[];
    }
  }

  if(existing.length){
    let series=existing[0];
    if(!series?.id) throw new Error('Existing Sonarr series has no internal ID');

    const seasons=Array.isArray(series.seasons)?series.seasons:[];
    const regularSeasons=seasons.filter(s=>Number(s.seasonNumber)!==0);
    const wasFullyMonitored=Boolean(series.monitored)&&regularSeasons.every(s=>Boolean(s.monitored));
    const specialsWereMonitored=seasons.some(s=>Number(s.seasonNumber)===0&&Boolean(s.monitored));
    if(!wasFullyMonitored||specialsWereMonitored){
      series.monitored=true;
      if(Array.isArray(series.seasons)) series.seasons=series.seasons.map(s=>({...s,monitored:Number(s.seasonNumber)===0?false:true}));
      series=await api('/api/v3/series/'+series.id,{method:'PUT',body:JSON.stringify(series)});
    }

    const [queue,commands]=await Promise.all([api('/api/v3/queue?page=1&pageSize=100&includeUnknownSeriesItems=true'),api('/api/v3/command')]);
    const activeDownload=(queue?.records||[]).some(x=>Number(x.seriesId)===Number(series.id));
    const activeSearch=(Array.isArray(commands)?commands:[]).some(c=>{
      const status=String(c.status||'').toLowerCase();
      const name=String(c.name||'').toLowerCase();
      const sid=Number(c.body?.seriesId||0);
      return ['queued','started'].includes(status)&&name.includes('seriessearch')&&(!sid||sid===Number(series.id));
    });
    let searchDue=false, searchTriggered=false, commandId=null, route=null, lastSearchAt=null;
    if(!activeDownload&&!activeSearch){
      const releaseSearch=await acquireSearchLock();
      try{
        const state=readSearchState();
        const key=String(series.id);
        const rawMeta=state[key];
        const last=typeof rawMeta==='string'
          ? (Date.parse(rawMeta)||0)
          : (Date.parse(rawMeta?.lastSearchAt||rawMeta?.lastAttemptAt||'')||0);
        const nextAttemptAt=typeof rawMeta==='object'&&rawMeta
          ? (Date.parse(rawMeta.nextAttemptAt||'')||0)
          : (last?last+SEARCH_COOLDOWN_MS:0);
        lastSearchAt=last?new Date(last).toISOString():null;
        searchDue=!nextAttemptAt || Date.now()>=nextAttemptAt || !wasFullyMonitored;

        const globalMeta=state[GLOBAL_SEARCH_KEY];
        const globalLast=typeof globalMeta==='string'
          ? (Date.parse(globalMeta)||0)
          : (Date.parse(globalMeta?.lastSearchAt||'')||0);
        const globalDue=!globalLast || (Date.now()-globalLast)>=GLOBAL_SEARCH_INTERVAL_MS;

        if(searchDue&&globalDue){
          const attemptStartedAt=new Date().toISOString();
          try{
            route=await grabNextSeriesRelease(series.id);
            searchTriggered=Boolean(route?.grabbed);
            commandId=route?.downloadClientId??null;

            const status=String(route?.status||'UNKNOWN');
            const shortRetry=['NO_ACCEPTABLE_RELEASE','NO_MISSING_AIRED_EPISODE','C411_PRIMARY_NO_GRAB'].includes(status);
            const retryMs=shortRetry?SEARCH_NO_RESULT_COOLDOWN_MS:SEARCH_COOLDOWN_MS;
            const finishedAt=new Date().toISOString();
            state[key]={
              lastAttemptAt:attemptStartedAt,
              lastSearchAt:finishedAt,
              lastStatus:status,
              nextAttemptAt:new Date(Date.now()+retryMs).toISOString()
            };
            state[GLOBAL_SEARCH_KEY]={lastSearchAt:finishedAt,lastStatus:status};
            writeSearchState(state);
          }catch(e){
            // Do not consume the per-series cooldown on infrastructure/search errors.
            // Only throttle globally until the next scheduled workflow run.
            const failedAt=new Date().toISOString();
            state[GLOBAL_SEARCH_KEY]={
              lastSearchAt:failedAt,
              lastStatus:'SEARCH_ERROR',
              error:String(e?.message||e||'Unknown search error').slice(0,300)
            };
            writeSearchState(state);
            route={grabbed:false,status:'SEARCH_ERROR',error:String(e?.message||e||'Unknown search error')};
          }
        }else if(searchDue&&!globalDue){
          route={
            grabbed:false,
            status:'GLOBAL_THROTTLED',
            nextGlobalSearchAt:new Date(globalLast+GLOBAL_SEARCH_INTERVAL_MS).toISOString()
          };
        }
      }finally{
        releaseSearch();
      }
    }

    console.log(JSON.stringify({ok:true,key:input.key,type:input.type,service:'sonarr',action:searchTriggered?'missing_grabbed':'arr_state_checked',title:series.title||input.title,year:series.year||input.year,sonarrId:series.id,monitored:Boolean(series.monitored),wasFullyMonitored,arrManaged:true,localFsCheckSkipped:true,episodeFileCount:Number(series.statistics?.episodeFileCount||0),activeDownload,activeSearch,searchDue,lastSearchAt,searchCooldownMinutes:60,noResultRetryMinutes:15,globalSearchIntervalMinutes:0,searchTriggered,commandId,route}));
    return;
  }

  if(!hit?.tvdbId){
    console.log(JSON.stringify({
      ok:true,key:input.key,type:input.type,service:'sonarr',
      action:'strict_match_not_found',title:input.title,year:input.year,
      tvdbFromPlex:tvdbFromPlex||null,searchTriggered:false
