  }

  let created=await api('/api/v3/series',{method:'POST',body:JSON.stringify({...hit,qualityProfileId:PROFILE,rootFolderPath:ROOT,monitored:true,seasonFolder:true,tags:[],addOptions:{monitor:'all',searchForMissingEpisodes:false}})});
