const output = [];
for (const item of $input.all()) {
  const raw = String(item.json.stdout || '').trim();
  let result;
  try { result = JSON.parse(raw); }
  catch (e) {
    result = {
      ok: false, service: 'unknown', action: 'invalid_output',
      error: 'Invalid processor JSON output: ' + e.message,
      raw: raw.slice(0, 500)
    };
  }
  output.push({ json: {
    ...result,
    processorExitCode: item.json.exitCode ?? null,
    processorStderr: String(item.json.stderr || '').trim()
  }});
}
return output;

