function clone(x) { return JSON.parse(JSON.stringify(x)); }
function parseUrl(value) {
  const u = new URL(String(value || '').trim());
  return {
    host: u.hostname,
    port: Number(u.port || (u.protocol === 'https:' ? 443 : 80)),
    useSsl: u.protocol === 'https:',
    urlBase: u.pathname && u.pathname !== '/' ? u.pathname.replace(/^\/|\/$/g, '') : ''
  };
}
function findField(client, name) {
  return (client.fields || []).find(f => String(f.name || '').toLowerCase() === String(name).toLowerCase());
}
function setField(client, name, value) { const f = findField(client, name); if (f) f.value = value; }
function fieldValue(client, name) { return findField(client, name)?.value; }
function isQbit(client) {
  return String(client?.implementation || '').toLowerCase() === 'qbittorrent' ||
         String(client?.implementationName || '').toLowerCase().includes('qbittorrent');
}
async function request(base, key, path, options = {}) {
  const response = await fetch(base + path, {
    ...options,
    headers: {
      'X-Api-Key': key,
      'Accept': 'application/json',
      'Content-Type': 'application/json',
      ...(options.headers || {})
    },
    signal: AbortSignal.timeout(15000)
  });
  const text = await response.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  if (!response.ok) {
    const err = new Error('HTTP ' + response.status + ' ' + path + ' :: ' + String(text).slice(0, 700));
    err.status = response.status;
    throw err;
  }
  return data;
}
async function upsertClient(base, key, existing, schema, spec) {
  const c = existing ? clone(existing) : clone(schema);
  if (!existing) delete c.id;
  c.name = spec.name;
  c.enable = true;
  c.priority = spec.priority;
  c.removeCompletedDownloads = spec.mode === 'decypharr';
  c.removeFailedDownloads = false;
  setField(c, 'host', spec.target.host);
  setField(c, 'port', spec.target.port);
  setField(c, 'useSsl', spec.target.useSsl);
  setField(c, 'urlBase', spec.target.urlBase);
  setField(c, 'category', spec.category);
  setField(c, 'movieCategory', spec.category);
  setField(c, 'tvCategory', spec.category);
  if (spec.mode === 'decypharr') {
    setField(c, 'apiKey', '');
    setField(c, 'username', base);
    setField(c, 'password', key);
  } else {
    setField(c, 'apiKey', spec.apiKey || '');
    if (spec.apiKey) {
      setField(c, 'username', '');
      setField(c, 'password', '');
    } else {
      if (spec.username != null) setField(c, 'username', spec.username);
      if (spec.password != null) setField(c, 'password', spec.password);
    }
  }
  return existing
    ? request(base, key, '/api/v3/downloadclient/' + existing.id, { method: 'PUT', body: JSON.stringify(c) })
    : request(base, key, '/api/v3/downloadclient', { method: 'POST', body: JSON.stringify(c) });
}
async function reconcileArr(label, arrCfg, category, decyCfg, qbitCfg) {
  const base = String(arrCfg?.url || '').replace(/\/$/, '');
  const key = String(arrCfg?.api_key || '').trim();
  if (!base || !key) throw new Error(label + ': missing URL/API key');
  const [clients, schemas] = await Promise.all([
    request(base, key, '/api/v3/downloadclient'),
    request(base, key, '/api/v3/downloadclient/schema')
  ]);
  const schema = (schemas || []).find(isQbit);
  if (!schema) throw new Error(label + ': qBittorrent schema not found');

  let decy = (clients || []).find(c => String(c.name || '').toLowerCase() === 'decypharr');
  decy = await upsertClient(base, key, decy, schema, {
    name: 'Decypharr', priority: 1, category, target: parseUrl(decyCfg.url), mode: 'decypharr'
  });

  const refreshed = await request(base, key, '/api/v3/downloadclient');
  let qbit = (refreshed || []).find(c => isQbit(c) && String(c.name || '').toLowerCase() !== 'decypharr');
  const qbitApiKey = String(qbitCfg.api_key || '').trim();
  const qbitUsername = qbitCfg.username == null ? null : String(qbitCfg.username);
  const qbitPassword = qbitCfg.password == null ? null : String(qbitCfg.password);

  if (!qbit && !qbitApiKey && qbitUsername == null && qbitPassword == null) {
    throw new Error(label + ': qBittorrent is missing and no qBittorrent secret is available in stack.json');
  }

  qbit = await upsertClient(base, key, qbit, schema, {
    name: qbit?.name || 'qBittorrent',
    priority: 10,
    category,
    target: parseUrl(qbitCfg.url),
    mode: 'qbittorrent',
    apiKey: qbitApiKey,
    username: qbitUsername,
    password: qbitPassword
  });

  // C411 always downloads through native qBittorrent, not the Decypharr
  // qBittorrent-compatible facade, regardless of default client priority.
  const c411Indexers=[];
  const allIndexers=await request(base,key,'/api/v3/indexer');
  for(const idx of (Array.isArray(allIndexers)?allIndexers:[])){
    if(!/\bC411\b/i.test(String(idx.name||'')))continue;
    let action='already_pinned';
    if(Number(idx.downloadClientId)!==Number(qbit.id)){
      const updated={...idx,downloadClientId:Number(qbit.id)};
      await request(base,key,'/api/v3/indexer/'+idx.id,{method:'PUT',body:JSON.stringify(updated)});
      action='pinned_to_qbittorrent';
    }
    c411Indexers.push({name:idx.name,id:idx.id,qbitId:qbit.id,action});
  }

  let tests = null;
  try {
    tests = await request(base, key, '/api/v3/downloadclient/testall', { method: 'POST', body: '{}' });
  } catch (e) {
    tests = { error: e.message };
  }

  const finalClients = await request(base, key, '/api/v3/downloadclient');
  const finalDecy = finalClients.find(c => Number(c.id) === Number(decy.id)) || decy;
  const finalQbit = finalClients.find(c => Number(c.id) === Number(qbit.id)) || qbit;

  return {
    label, category,
    decypharr: {
      id: finalDecy.id, name: finalDecy.name, enabled: finalDecy.enable, priority: finalDecy.priority,
      host: fieldValue(finalDecy, 'host'), port: fieldValue(finalDecy, 'port'), category: fieldValue(finalDecy, 'category') ?? fieldValue(finalDecy, 'movieCategory') ?? fieldValue(finalDecy, 'tvCategory')
    },
    qbittorrent: {
      id: finalQbit.id, name: finalQbit.name, enabled: finalQbit.enable, priority: finalQbit.priority,
      host: fieldValue(finalQbit, 'host'), port: fieldValue(finalQbit, 'port'),
      category: fieldValue(finalQbit, 'category') ?? fieldValue(finalQbit, 'movieCategory') ?? fieldValue(finalQbit, 'tvCategory'),
      apiKeyConfigured: Boolean(String(fieldValue(finalQbit, 'apiKey') || '').trim())
    },
    tests,c411Indexers
  };
}
(async () => {
  if (!fs.existsSync(CFG)) return emit({ service:'download-client-reconcile', ok:false, status:'CONFIG_NOT_FOUND', path:CFG });
  let cfg;
  try { cfg = JSON.parse(fs.readFileSync(CFG,'utf8')); }
  catch (e) { return emit({ service:'download-client-reconcile', ok:false, status:'CONFIG_INVALID', error:e.message }); }
  if (!cfg.decypharr?.url || !cfg.qbittorrent?.url) {
    return emit({ service:'download-client-reconcile', ok:false, status:'CLIENT_CONFIG_MISSING' });
  }
  const results = [];
  for (const [label, arrCfg, category] of [
    ['Radarr', cfg.radarr, 'radarr'],
    ['Sonarr', cfg.sonarr, 'sonarr']
  ]) {
