    catch (e) { results.push({ ok:false, label, category, error:e.message }); }
  }

  emit({
    service:'download-client-reconcile',
    ok:results.every(x=>x.ok),
    status:results.every(x=>x.ok)?'CONFIGURED':'PARTIAL',
    policy:{preferred:'Decypharr',c411:'qBittorrent forced per indexer',fallback:'qBittorrent',categories:{radarr:'radarr',sonarr:'sonarr'}},
    results
  });
})().catch(e => emit({ service:'download-client-reconcile', ok:false, status:'ERROR', error:e.message }));
