node <<'NODE'
'use strict';
const fs=require('fs');
const path=require('path');
const configFile=process.env.SYNOPLEX_STACK_JSON||'/data/PlexMediaServer/stack.json';
const families=[
  {id:'city-hunter',title:'City Hunter / Nicky Larson',re:/\b(?:city[\s._-]*hunter|nicky[\s._-]*larson)\b/i,sonarr:'City Hunter'},
  {id:'buffy',title:'Buffy the Vampire Slayer',re:/\bbuffy\b/i,sonarr:'Buffy the Vampire Slayer'},
  {id:'charmed',title:'Charmed',re:/\bcharmed\b/i,sonarr:'Charmed'}
];
const videoExt=new Set(['.mkv','.mp4','.avi','.m4v','.mov','.ts','.m2ts','.webm']);
function emit(report){console.log(JSON.stringify({service:'duplicate-manifest-audit',mode:'READ_ONLY',...report}));}
async function get(base,headers,route){
  const response=await fetch(base+route,{method:'GET',headers,signal:AbortSignal.timeout(30000)});
  const body=await response.text();
  if(!response.ok)throw Error('GET '+route+' HTTP '+response.status+' '+body.slice(0,180));
  try{return JSON.parse(body)}catch{throw Error('Invalid JSON from '+route)}
}
function scope(name,familyId){
  if(/\b(?:integrale?|complete|collection|s01[\s._-]*s04)\b/i.test(name)||
    (familyId==='city-hunter'&&/\[multi\][\s._-]*\[br\]/i.test(name)))return 'integral';
  const m=name.match(/(?:^|[\s._-])s(\d{1,2})(?=$|[\s._-])/i);
  if(m)return 'season-'+Number(m[1]);
  return 'unknown';
}
function key(s,e){return 'S'+String(s).padStart(2,'0')+'E'+String(e).padStart(3,'0');}
function episodesForFile(file,family,bySe){
  const name=String(file.name||'');
  const basename=path.posix.basename(name);
  const keys=new Set();
  for(const m of name.matchAll(/(?:^|[^a-z0-9])s(\d{1,2})e(\d{1,3})(?:e(\d{1,3}))?/gi)){
    for(const e of [m[2],m[3]].filter(Boolean)){
      const ep=key(Number(m[1]),Number(e));
      keys.add(family==='city-hunter'?(bySe.get(ep)||ep):ep);
    }
  }
  if(!keys.size){
    const s=name.match(/(?:^|[^a-z0-9])s(?:eason)?[\s._-]?0?(\d{1,2})(?:[^a-z0-9]|$)/i);
    const e=basename.match(/(?:^|[^a-z0-9])e(?:p)?[\s._-]?0?(\d{1,3})(?:[^a-z0-9]|$)/i);
    if(s&&e){const ep=key(Number(s[1]),Number(e[1]));keys.add(family==='city-hunter'?(bySe.get(ep)||ep):ep);}
  }
  if(family==='city-hunter'&&!keys.size){
    const absolute=basename.match(/^(\d{3})\s*[-. ]/)||basename.match(/^\[DragonMax\]\s*Nicky Larson\s*-\s*(\d{3})\.mkv$/i);
    if(absolute)keys.add('A'+String(Number(absolute[1])).padStart(3,'0'));
  }
  return [...keys];
}
async function main(){
  if(!fs.existsSync(configFile))throw Error('NAS config not found');
  const cfg=JSON.parse(fs.readFileSync(configFile,'utf8'));
  const qb=String(cfg.qbittorrent?.url||'').replace(/\/$/,'');
  const sb=String(cfg.sonarr?.url||'').replace(/\/$/,'');
  const sk=String(cfg.sonarr?.api_key||'');
  if(!qb||!sb||!sk||!cfg.qbittorrent?.username||!cfg.qbittorrent?.password)throw Error('Missing qBittorrent/Sonarr configuration');
  const login=await fetch(qb+'/api/v2/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Referer:qb+'/'},
    body:new URLSearchParams({username:String(cfg.qbittorrent.username),password:String(cfg.qbittorrent.password)}),signal:AbortSignal.timeout(15000)});
  const loginText=(await login.text()).trim();
  if(!login.ok||loginText==='Fails.')throw Error('qBittorrent login failed');
  const session=String(login.headers.get('set-cookie')||'').split(';')[0];
  const qh={Accept:'application/json',Referer:qb+'/'};
  if(session)qh.Cookie=session;
  const sh={'X-Api-Key':sk,Accept:'application/json'};
  const [torrents,series]=await Promise.all([get(qb,qh,'/api/v2/torrents/info'),get(sb,sh,'/api/v3/series')]);
  if(!Array.isArray(torrents)||!Array.isArray(series))throw Error('Unexpected qBittorrent/Sonarr response');
  const groups=[];
  for(const fam of families){
    const matches=torrents.filter(t=>fam.re.test(String(t.name||''))&&!(fam.id==='city-hunter'&&/\b2024\b/.test(t.name)));
    if(matches.length<2)continue;
    const classified=matches.map(t=>({torrent:t,scope:scope(String(t.name||''),fam.id)}));
    const integrals=classified.filter(x=>x.scope==='integral');
    const seasons=classified.filter(x=>x.scope.startsWith('season-'));
    if(!integrals.length||(!seasons.length&&integrals.length<2))continue;
    const s=series.find(x=>String(x.title||'').toLowerCase()===fam.sonarr.toLowerCase());
    const [episodeFiles,episodes]=s?await Promise.all([
      get(sb,sh,'/api/v3/episodefile?seriesId='+encodeURIComponent(s.id)),
      fam.id==='city-hunter'?get(sb,sh,'/api/v3/episode?seriesId='+encodeURIComponent(s.id)+'&includeImages=false'):Promise.resolve([])
    ]):[[],[]];
    const bySe=new Map();
    if(Array.isArray(episodes))for(const e of episodes)if(Number(e.absoluteEpisodeNumber)>0)
      bySe.set(key(Number(e.seasonNumber),Number(e.episodeNumber)),
        'A'+String(Number(e.absoluteEpisodeNumber)).padStart(3,'0'));
    const items=[];
    let cityBrSizeEvidence=null;
    for(const x of classified){
      const t=x.torrent;
      let files=[],error=null;
      try{
        files=await get(qb,qh,'/api/v2/torrents/files?hash='+encodeURIComponent(t.hash));
        if(!Array.isArray(files))throw Error('Torrent files are not an array');
      }catch(e){files=[];error=e.message;}
      const videos=files.filter(f=>videoExt.has(path.posix.extname(String(f.name||'')).toLowerCase())&&Number(f.priority)!==0);
      const ids=new Set();
      for(const f of videos)for(const id of episodesForFile(f,fam.id,bySe))ids.add(id);
      // Strong read-only indication of City Hunter's BR source (not a full hash proof).
      if(fam.id==='city-hunter'&&String(t.name||'')==='City Hunter - Nicky Larson [Multi] [BR]'){
        const regular=(Array.isArray(episodes)?episodes:[]).filter(e=>Number(e.seasonNumber)>0)
          .sort((a,b)=>Number(a.seasonNumber)-Number(b.seasonNumber)||Number(a.episodeNumber)-Number(b.episodeNumber));
        const libraryById=new Map((Array.isArray(episodeFiles)?episodeFiles:[]).map(f=>[Number(f.id),f]));
        const root=String(cfg.paths?.media_root||'').replace(/\/$/,'');
        const mapped=String(cfg.paths?.n8n_media_root||'').replace(/\/$/,'');
        const seen=new Set();
        const check={sourceTorrent:t.name,regularEpisodes:regular.length,
          sourceVideoCount:videos.length,compared:0,identicalSizes:0,mismatchedSizes:0,
          missingLibraryFiles:0,unmappedSourceFiles:0,duplicates:0,manifestIncomplete:0};
        for(const f of videos){
          const match=path.posix.basename(String(f.name||'')).match(/^(\d{3})\s*-/);
          const n=Number(match?.[1]||0);
          if(!n||n>regular.length){check.unmappedSourceFiles++;continue;}
          if(seen.has(n)){check.duplicates++;continue;}
          seen.add(n);
          const e=regular[n-1],lib=libraryById.get(Number(e?.episodeFileId||0));
          if(!lib?.path||!root||!mapped||!String(lib.path).startsWith(root+'/')){
            check.missingLibraryFiles++;continue;
          }
          try{
            const st=fs.statSync(mapped+String(lib.path).slice(root.length));
            if(!st.isFile()){check.missingLibraryFiles++;continue;}
            check.compared++;
            if(Number(f.progress)===1&&Number(f.size)===st.size)check.identicalSizes++;
            else check.mismatchedSizes++;
            if(Number(f.progress)!==1)check.manifestIncomplete++;
          }catch{check.missingLibraryFiles++;}
        }
        check.status=regular.length===140&&videos.length===140&&check.compared===140&&
          check.identicalSizes===140&&check.mismatchedSizes===0&&check.unmappedSourceFiles===0&&
          check.missingLibraryFiles===0&&check.duplicates===0&&check.manifestIncomplete===0
          ?'STRONG_140_OF_140_SIZE_MATCH_NOT_HASH_VERIFIED'
          :'BR_SOURCE_MANIFEST_NOT_FULLY_PROVEN';
        cityBrSizeEvidence=check;
      }
      items.push({
        name:String(t.name||''),hashPrefix:String(t.hash||'').slice(0,12),
        category:String(t.category||''),tags:String(t.tags||''),
        savePath:String(t.save_path||''),scope:x.scope,complete:Number(t.progress)===1,
        videoFiles:videos.length,mappedEpisodeCount:ids.size,
        sizeBytes:videos.reduce((sum,f)=>sum+Number(f.size||0),0),
        auditError:error,episodeIds:ids
      });
    }
    const primary=items.filter(x=>x.scope==='integral');
    const comparisons=[];
    for(const other of items){
      if(other.scope==='integral'&&other===primary[0])continue;
      const primaryKeys=new Set(primary[0].episodeIds);
      const overlap=[...other.episodeIds].filter(x=>primaryKeys.has(x));
      const verified=primaryKeys.size>0&&other.episodeIds.size>0;
      comparisons.push({
        source:other.name,
        comparedWith:primary[0].name,
        identicalEpisodeIds:overlap.length,
        sourceEpisodeIds:other.episodeIds.size,
        integralEpisodeIds:primaryKeys.size,
        sampleOverlap:overlap.slice(0,6),
        status:verified?(overlap.length?'EPISODE_ID_OVERLAP':'NO_EPISODE_ID_OVERLAP'):'POSSIBLE_OVERLAP_MANIFEST_UNVERIFIED',
        byteIdentity:'NOT_CHECKED',deletionSafe:false
      });
    }
    const registered=Array.isArray(episodeFiles)?episodeFiles.length:0;
    const nroot=String(cfg.paths?.media_root||'').replace(/\/$/,'');
    const lroot=String(cfg.paths?.n8n_media_root||'').replace(/\/$/,'');
    const isOnDisk=p=>{const val=String(p||'');return Boolean(nroot&&lroot&&val.startsWith(nroot+'/')&&fs.existsSync(lroot+val.slice(nroot.length)))};
    const physical=Array.isArray(episodeFiles)?episodeFiles.filter(f=>isOnDisk(f.path)).length:0;
    groups.push({
      family:fam.id,title:fam.title,sonarrSeriesId:s?.id||null,
      cityBrSizeEvidence,
      sonarrRegisteredFiles:registered,sonarrPhysicalFiles:physical,sonarrStaleFiles:registered-physical,
      comparisonCount:comparisons.length,
      episodeOverlapCandidates:comparisons.filter(c=>c.identicalEpisodeIds>0).length,
      needsManifestVerification:comparisons.filter(c=>c.status==='POSSIBLE_OVERLAP_MANIFEST_UNVERIFIED').length,
      torrents:items.map(({episodeIds,...rest})=>rest),
      comparisons
    });
  }
  emit({
    ok:true,status:groups.length?'CANDIDATES_FOUND':'NO_INTEGRAL_SEASON_OVERLAP',
    scannedTorrents:torrents.length,groups,
    summary:{groups:groups.length,
      competingTorrents:groups.reduce((n,g)=>n+g.comparisonCount,0),
      episodeOverlapCandidates:groups.reduce((n,g)=>n+g.episodeOverlapCandidates,0),
      uncertainCandidates:groups.reduce((n,g)=>n+g.needsManifestVerification,0)},
    safety:{moved:0,removed:0,paused:0,importsSubmitted:0,
      note:'Audit de métadonnées. Les épisodes identiques en numéro ne prouvent pas des octets identiques. Ne jamais supprimer sans validation manifest, taille, inode et copies indépendantes.'}
  });
}
main().catch(e=>emit({ok:false,status:'AUDIT_FAILED',error:e.message,
  safety:{moved:0,removed:0,paused:0,importsSubmitted:0}}));
