return $input.all().map(item => {
  let report;
  try { report=JSON.parse(String(item.json.stdout||'')); }
  catch (e) { return {json:{...item.json, businessStatus:'IMPORT_REPORT_UNREADABLE', businessOk:false, auditError:e.message}}; }
  const s=report.summary||{};
  const pending=Number(s.libraryCoverageUnconfirmedTotal??s.importUnconfirmedTotal??0);
  const provenancePending=Number(s.sourceProvenanceUnconfirmedTotal??s.importUnconfirmedTotal??0);
  const covered=Number(s.libraryCoverageVerifiedTotal||0);
  const issues=[];
  if(pending>0)issues.push({code:'LIBRARY_COVERAGE_UNCONFIRMED',count:pending});
  if(Number(s.errors||0)>0)issues.push({code:'IMPORTER_ERRORS',count:Number(s.errors)});
  const br=report.cityBrSwitch;
  if(br?.status==='BR_COMPLETE_LOCKED')issues.push({code:'CITY_BR_SOURCE_NOT_PROVEN',detail:'140 episodes visibles ne prouvent pas une origine BR; audit manifeste requis'});
  if(report.cityHunterRepair?.status==='SOURCE_OR_SERIES_NOT_FOUND')issues.push({code:'CITY_BR_REPAIR_SOURCE_GUARD',detail:'La source BR ne satisfait pas les gardes de la réparation'});
  if(report.hunterRepair?.status==='HUNTER_REPAIR_BLOCKED')issues.push({code:'HUNTER_REPAIR_BLOCKED',reason:report.hunterRepair.reason});
  if(report.bleachAudit?.status==='NO_SOURCE')issues.push({code:'BLEACH_SOURCE_NOT_FOUND'});
  if(String(report.bleachAudit?.status||'').startsWith('SUSPENDED')) issues.push({code:'BLEACH_AUTOREPAIR_SUSPENDED',detail:'Plex Bleach 366 episodes corriges. Ne pas reactiver les anciens renommages automatiques S01E absolus.'});
  if(report.ok===false)issues.push({code:'IMPORTER_REPORT_NOT_OK',status:report.status});
  return {json:{...item.json,businessOk:issues.length===0,businessStatus:issues.length?'ATTENTION_REQUIRED':'VERIFIED',
    importerStatus:report.status||null,importerSummary:s,cityBrClaim:br?.status||null,
    cityBrVerifiedFromSource:false,issues,sourceReportAvailable:true,
    importVerification:{libraryCoverageVerified:covered,libraryCoveragePending:pending,sourceProvenancePending:provenancePending,sourceProvenanceIsNotAnImportFailure:true}}};
});

