node <<'NODE'
'use strict';
const fs=require('fs');
const c=JSON.parse(fs.readFileSync('/data/PlexMediaServer/stack.json','utf8'));
const S=String(c.sonarr?.url||'').replace(/\/$/,'');
const H={'X-Api-Key':c.sonarr?.api_key,Accept:'application/json','Content-Type':'application/json'};
const ENABLE_SEARCH=true; // DRY RUN initially. Only enable after validating real episode selection.
const MAX_PER_RUN=6;
const MAX_QUEUED_SEARCH=1;
const SEARCH_COOLDOWN_MS=3*60*60*1000;
const RETRY_AFTER_ERROR_MS=25*60*1000;
const STATE='/data/PlexMediaServer/synoplex-sonarr-missing-search-v1.json';
const LOCK='/home/node/.n8n/.synoplex-sonarr-missing-search.lock';
const emit=x=>console.log(JSON.stringify({service:'sonarr-monitored-missing-auto-search',mode:ENABLE_SEARCH?'SEARCH':'DRY_RUN',...x}));
async function api(route,method='GET',body){
 const r=await fetch(S+route,{method,headers:H,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(45000)});
 const txt=await r.text();let data;try{data=JSON.parse(txt)}catch{data=txt}
 if(!r.ok)throw Error(method+' '+route+' HTTP '+r.status+' '+String(txt).slice(0,220));return data;
}
function stateRead(){try{const x=JSON.parse(fs.readFileSync(STATE,'utf8'));return x&&typeof x==='object'?x:{}}catch{return {}}}
function stateSave(s){
 const tmp=STATE+'.tmp-'+process.pid;
 fs.writeFileSync(tmp,JSON.stringify(s,null,2),{mode:0o600});fs.renameSync(tmp,STATE);
}
function queuedEpisodes(queue){
 const set=new Set();
 for(const r of queue?.records||[]){
  if(r.seriesId&&r.episodeId)set.add(Number(r.episodeId));
  if(Array.isArray(r.episodeIds))for(const id of r.episodeIds)set.add(Number(id));
  for(const ep of r.episodes||[])if(ep.id)set.add(Number(ep.id));
 }
 return set;
}
(async()=>{
 let lockFd=null;
 try{
  if(ENABLE_SEARCH){
   try{const st=fs.statSync(LOCK);if(Date.now()-st.mtimeMs>15*60*1000)fs.unlinkSync(LOCK)}
   catch(e){if(e.code!=='ENOENT')throw e}
   try{lockFd=fs.openSync(LOCK,'wx',0o600)}
   catch(e){if(e.code==='EEXIST'){emit({ok:true,status:'SEARCH_ALREADY_RUNNING'});return}throw e}
  }
  const [shows,queue,cmds]=await Promise.all([
   api('/api/v3/series'),api('/api/v3/queue?page=1&pageSize=500&includeUnknownSeriesItems=true'),api('/api/v3/command')
  ]);
  const searches=(Array.isArray(cmds)?cmds:[]).filter(x=>
   /^(EpisodeSearch|SeasonSearch|SeriesSearch|MissingEpisodeSearch|CutoffUnmetEpisodeSearch)$/i.test(String(x.name||''))&&
   ['queued','started'].includes(String(x.status||'').toLowerCase()));
  if(searches.length>=MAX_QUEUED_SEARCH){
   emit({ok:true,status:'SONARR_SEARCH_BUSY',runningSearches:searches.map(x=>({id:x.id,name:x.name,status:x.status})).slice(0,5)});return;
  }
  const waiting=queuedEpisodes(queue);
  const now=Date.now(),state=stateRead();
  const eligibleShows=(Array.isArray(shows)?shows:[]).filter(x=>
   x.monitored===true&&Number(x.id)>0&&
   String(x.path||'').startsWith('/volume1/VideoFactory/_Plex/media/Series/'));
  const all=[],bySeries=[];
  // Query all existing Sonarr series, not only the Plex watchlist. Never search specials or unaired episodes.
  let idx=0;
  async function work(){
   while(idx<eligibleShows.length){
    const s=eligibleShows[idx++];
    try{
     const eps=await api('/api/v3/episode?seriesId='+s.id);
     const monitoredSeasons=new Set((s.seasons||[]).filter(x=>Number(x.seasonNumber)>0&&x.monitored===true).map(x=>Number(x.seasonNumber)));
     const viable=(Array.isArray(eps)?eps:[]).filter(e=>
      e.monitored===true&&!e.hasFile&&Number(e.seasonNumber)>0&&monitoredSeasons.has(Number(e.seasonNumber))&&
      !!e.airDateUtc&&Number.isFinite(Date.parse(e.airDateUtc))&&Date.parse(e.airDateUtc)<=now&&
      !waiting.has(Number(e.id)));
     const unsearched=viable.filter(e=>!state.episodes?.[e.id]||now-Date.parse(state.episodes[e.id].attemptedAt||0)>=SEARCH_COOLDOWN_MS);
     const rows=unsearched.map(e=>({id:Number(e.id),seriesId:Number(s.id),series:s.title,season:Number(e.seasonNumber),
      episode:Number(e.episodeNumber),airDateUtc:e.airDateUtc,attemptedAt:state.episodes?.[e.id]?.attemptedAt||null}));
     all.push(...rows);
     bySeries.push({series:s.title,id:s.id,missingReady:viable.length,eligibleToSearch:rows.length});
    }catch(e){bySeries.push({series:s.title,id:s.id,error:e.message})}
   }
  }
  await Promise.all(Array.from({length:4},work));
  const priority=(e)=>e.seriesId===56&&e.season===17?0:1;
  const selected=all.sort((a,b)=>priority(a)-priority(b)||
    Date.parse(a.attemptedAt||'1970-01-01')-Date.parse(b.attemptedAt||'1970-01-01')||
    a.seriesId-b.seriesId||a.season-b.season||a.episode-b.episode).slice(0,MAX_PER_RUN);
  if(!selected.length){emit({ok:true,status:'NOTHING_TO_SEARCH',seriesChecked:eligibleShows.length,eligibleEpisodes:all.length,
    queueItems:(queue.records||[]).length,bySeries:bySeries.filter(x=>x.missingReady||x.error)});return}
  if(!ENABLE_SEARCH){emit({ok:true,status:'READY_TO_SEARCH',seriesChecked:eligibleShows.length,
    selected,eligibleEpisodes:all.length,bySeries:bySeries.filter(x=>x.missingReady||x.error)});return}
  const ids=selected.map(x=>x.id);
  let command;
  try{command=await api('/api/v3/command','POST',{name:'EpisodeSearch',episodeIds:ids})}
  catch(e){
   const old=state.episodes||{};
   for(const row of selected)old[row.id]={attemptedAt:new Date(now-SEARCH_COOLDOWN_MS+RETRY_AFTER_ERROR_MS).toISOString(),status:'ERROR',error:e.message.slice(0,240)};
   state.episodes=old;state.lastError=e.message;stateSave(state);
   throw e;
  }
  if(!command?.id)throw Error('Sonarr did not return an EpisodeSearch command ID');
  state.episodes=state.episodes||{};
  for(const row of selected)state.episodes[row.id]={attemptedAt:new Date(now).toISOString(),status:'REQUESTED',commandId:command.id};
  state.last={at:new Date(now).toISOString(),episodeIds:ids,commandId:command.id};
  stateSave(state);
  emit({ok:true,status:'SONARR_EPISODE_SEARCH_SUBMITTED',seriesChecked:eligibleShows.length,
   selected,commandId:command.id,commandStatus:command.status,eligibleEpisodes:all.length,
   downloadRouting:'SONARR_CONFIGURED_INDEXERS_AND_CLIENTS',torrentFilesMoved:0,filesDeleted:0});
 }finally{if(lockFd!==null){try{fs.closeSync(lockFd)}catch{}try{fs.unlinkSync(LOCK)}catch{}}}
})().catch(e=>emit({ok:false,status:'SEARCH_ERROR',error:e.message}));
