const fs=require('fs');
(async()=>{
  const cfg=JSON.parse(fs.readFileSync(process.env.SYNOPLEX_STACK_JSON||'/data/PlexMediaServer/stack.json','utf8'));
  const base=String(cfg.qbittorrent?.url||'').replace(/\/$/,'');
  if(!base||!cfg.qbittorrent?.username||!cfg.qbittorrent?.password)throw Error('QBIT_CONFIG_MISSING');
  const login=await fetch(base+'/api/v2/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Referer:base+'/'},body:new URLSearchParams({username:String(cfg.qbittorrent.username),password:String(cfg.qbittorrent.password)}),signal:AbortSignal.timeout(15000)});
  if(!login.ok||(await login.text()).trim()==='Fails.')throw Error('QBIT_LOGIN_FAILED');
  const headers={Cookie:String(login.headers.get('set-cookie')||'').split(';')[0],Referer:base+'/',Accept:'application/json'};
  async function get(p){const r=await fetch(base+p,{headers,signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('QBIT_GET_HTTP_'+r.status);return r.json();}
  async function stop(hash){const r=await fetch(base+'/api/v2/torrents/stop',{method:'POST',headers:{...headers,'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({hashes:hash}),signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('QBIT_STOP_HTTP_'+r.status);}
  const rows=await get('/api/v2/torrents/info');
  if(!Array.isArray(rows))throw Error('QBIT_INFO_INVALID');
  const completed=rows.filter(t=>Number(t.progress)===1);
  const active=completed.filter(t=>!/paused|stopped/i.test(String(t.state||''))&&!/moving|checking/i.test(String(t.state||'')));
  const report={service:'synoplex-c411-only-seeding',ok:true,policy:'STOP_COMPLETED_NON_C411_ONLY',total:rows.length,completed:completed.length,alreadyStopped:completed.filter(t=>/paused|stopped/i.test(String(t.state||''))).length,c411Kept:0,nonC411Stopped:0,stopErrors:[],trackerErrors:[],skippedBusy:completed.filter(t=>/moving|checking/i.test(String(t.state||''))).length,c411WithoutTag:0,nonC411WithTag:0,stoppedSample:[]};
  const stoppedHashes=[];
  const c411Host=h=>h==='c411.org'||h.endsWith('.c411.org')||h==='c411.tw'||h.endsWith('.c411.tw');
  const isC411Url=url=>{try{return c411Host(new URL(String(url||'')).hostname.toLowerCase())}catch{return false}};
  let cursor=0;
  async function worker(){
    while(cursor<active.length){
      const t=active[cursor++];
      try{
        const trackers=await get('/api/v2/torrents/trackers?hash='+encodeURIComponent(t.hash));
        if(!Array.isArray(trackers))throw Error('TRACKER_LIST_INVALID');
        const fromC411=isC411Url(t.tracker)||(trackers.some(tr=>isC411Url(tr.url)));
        const tagged=String(t.tags||'').split(',').some(v=>v.trim()==='seed-c411');
        if(fromC411){report.c411Kept++;if(!tagged)report.c411WithoutTag++;continue;}
        if(tagged)report.nonC411WithTag++;
        try{
          await stop(String(t.hash));
          report.nonC411Stopped++;
          stoppedHashes.push(String(t.hash));
          if(report.stoppedSample.length<12)report.stoppedSample.push({torrent:t.name,previousState:t.state,category:t.category});
        }catch(e){report.stopErrors.push({name:t.name,error:String(e.message)});}
      }catch(e){report.trackerErrors.push({name:t.name,error:String(e.message)});}
    }
  }
  await Promise.all(Array.from({length:Math.min(6,active.length)},worker));
  const latest=await get('/api/v2/torrents/info');
  const latestByHash=new Map(latest.map(t=>[String(t.hash),t]));
  report.nonC411StillActive=stoppedHashes.filter(hash=>{const t=latestByHash.get(hash);return t&&!/paused|stopped/i.test(String(t.state||''));}).length;
  report.runningCompletedTotal=latest.filter(t=>Number(t.progress)===1&&!/paused|stopped|moving|checking/i.test(String(t.state||''))).length;
  report.ok=report.stopErrors.length===0&&report.trackerErrors.length===0&&report.nonC411StillActive===0;
  console.log(JSON.stringify(report));
  if(!report.ok)process.exitCode=2;
})().catch(e=>{console.log(JSON.stringify({service:'synoplex-c411-only-seeding',ok:false,error:String(e.message)}));process.exitCode=1});
